// =============================================================
// Interactive Telegram Agent v5.0:
// - Handles BOTH text messages (/commands, free chat) AND One-Tap Inline Buttons (callback_query)
// - Built-in ⚡ BetPawa Slip Helper (parses any TZS amount: 10,000, 20k, 50000, etc.)
// =============================================================
const msg = $input.first().json || {};
const cb = msg.callback_query || null;
const mObj = cb ? (cb.message || {}) : (msg.message || {});

const rawText = cb
  ? String(cb.data || '').trim()
  : String(mObj.text || '').trim();
const chatId = String((mObj.chat && mObj.chat.id) || (cb && cb.from && cb.from.id) || '');
const fromId = String((cb && cb.from && cb.from.id) || (mObj.from && mObj.from.id) || '');
const ownerId = String($env.ALTRAWARE_OWNER_TG_ID || '8051901138').trim();

if (!rawText) return [{ json: { skip: true, reason: 'empty message' } }];
if (ownerId && fromId !== ownerId) return [{ json: { skip: true, reason: 'not owner' } }];

const sd = $getWorkflowStaticData('global');
const fbPicksText = sd.lastFootballPicks || 'Bado hakuna picks za Football za leo. Subiri saa 09:00 / 14:00 / 19:00 EAT.';
const bbPicksText = sd.lastBasketballPicks || 'Bado hakuna picks za NBA Basketball za leo. Subiri saa 09:00 / 14:00 / 19:00 EAT.';
const fbAnchor = sd.lastFootballAnchor || null;
const bbAnchor = sd.lastBasketballAnchor || null;
const lastTime = sd.lastPicksTime || 'Leo';

const lower = rawText.toLowerCase();

// Detect TZS amount in user message (e.g. "Nina TZS 10,000 leo", "20k", "50000", "15,000")
function extractTzsAmount(str) {
  const s = String(str || '').toLowerCase();
  const kMatch = s.match(/(\d+(?:\.\d+)?)\s*k\b/);
  if (kMatch) {
    const val = Math.round(parseFloat(kMatch[1]) * 1000);
    if (val >= 500 && val <= 50000000) return val;
  }
  const numMatches = s.match(/\b\d{1,3}(?:,\d{3})+\b|\b\d{3,8}\b/g);
  if (numMatches) {
    for (const m of numMatches) {
      const val = parseInt(m.replace(/,/g, ''), 10);
      if (val >= 500 && val <= 50000000) return val;
    }
  }
  return null;
}

const isBankrollReq =
  lower === 'cmd_bankroll' ||
  lower === '/bankroll' ||
  lower === '/mtaji' ||
  /betpawa|gawa|mtaji|mkeka|slip|nina\s*(tzs|tsh)?\s*\d/i.test(lower);

const detectedTzs = extractTzsAmount(rawText);

function buildBetPawaSlip(amountTzs) {
  const total = amountTzs || 10000;
  const stakeFb = Math.round((total * 0.40) / 100) * 100;
  const stakeBb = Math.round((total * 0.40) / 100) * 100;
  const stakeCombo = total - stakeFb - stakeBb;

  const fbName = fbAnchor ? `${fbAnchor.match} → ${fbAnchor.market}` : 'Football Safe Anchor #1 ya Leo';
  const fbOdds = fbAnchor ? Number(fbAnchor.odds) : 1.35;
  const fbKick = fbAnchor ? fbAnchor.kickoff : 'Leo';

  const bbName = bbAnchor ? `${bbAnchor.match} → ${bbAnchor.market}` : 'NBA Safe Anchor #1 ya Leo';
  const bbOdds = bbAnchor ? Number(bbAnchor.odds) : 1.35;
  const bbKick = bbAnchor ? bbAnchor.kickoff : 'Usiku huu';

  const comboOdds = +(fbOdds * bbOdds).toFixed(2);
  const retFb = Math.round(stakeFb * fbOdds);
  const retBb = Math.round(stakeBb * bbOdds);
  const retCombo = Math.round(stakeCombo * comboOdds);
  const totalRet = retFb + retBb + retCombo;
  const netProfit = totalRet - total;
  const roiPct = ((netProfit / total) * 100).toFixed(1);

  return (
    `⚡ BETPAWA SLIP HELPER — MGAWO WA TZS ${total.toLocaleString()}\n` +
    `📅 Kulingana na Anchors Bora za Leo (${lastTime})\n` +
    `━━━━━━━━━━━━━━━━━━━━━━\n` +
    `🎫 TICKET 1 (40% — Single ⚽ Football Anchor):\n` +
    `   📌 ${fbName} @ ${fbOdds.toFixed(2)} (${fbKick})\n` +
    `   💰 Weka: TZS ${stakeFb.toLocaleString()} → Malipo: TZS ${retFb.toLocaleString()}\n\n` +
    `🎫 TICKET 2 (40% — Single 🏀 NBA Anchor):\n` +
    `   📌 ${bbName} @ ${bbOdds.toFixed(2)} (${bbKick})\n` +
    `   💰 Weka: TZS ${stakeBb.toLocaleString()} → Malipo: TZS ${retBb.toLocaleString()}\n\n` +
    `🎫 TICKET 3 (20% — Safe 2-Leg Double ⚽ × 🏀):\n` +
    `   📌 Football Anchor × NBA Anchor @ ${comboOdds.toFixed(2)}\n` +
    `   💰 Weka: TZS ${stakeCombo.toLocaleString()} → Malipo: TZS ${retCombo.toLocaleString()}\n\n` +
    `━━━━━━━━━━━━━━━━━━━━━━\n` +
    `📊 HESABU YA POCHI:\n` +
    `• Jumla ya Mtaji: TZS ${total.toLocaleString()}\n` +
    `• Zikishinda Zote: TZS ${totalRet.toLocaleString()} (Faida Safi: +TZS ${netProfit.toLocaleString()} | +${roiPct}%)\n` +
    `• Ulinzi (Safety Net): Hata moja ikiteleza, single nyingine inakurudishia sehemu kubwa ya mtaji!\n\n` +
    `💡 Unataka mgawo wa kiasi kingine? Andika tu mfano: "Nina 25,000 leo" au "Nina 50k"!`
  );
}

let action = 'chat';
let instantReply = '';

if (lower === 'cmd_football' || lower === '/football') {
  action = 'football';
  instantReply =
    `⚽ HERMES FOOTBALL PICKS ZA LEO\n` +
    `📅 Updated: ${lastTime}\n` +
    `━━━━━━━━━━━━━━━━━━━━━━\n` +
    `${fbPicksText}\n\n` +
    `💬 Ukitaka ufafanuzi wa mechi maalum, andika jina la timu (mfano: "Chambua mechi ya Lazio").`;
} else if (lower === 'cmd_nba' || lower === '/basketball' || lower === '/nba') {
  action = 'nba';
  instantReply =
    `🏀 HERMES NBA BASKETBALL PICKS ZA LEO\n` +
    `📅 Updated: ${lastTime}\n` +
    `━━━━━━━━━━━━━━━━━━━━━━\n` +
    `${bbPicksText}\n\n` +
    `📘 Kumbuka: ML = Timu kushinda (+OT) | SPREAD -5.5 = Ishinde kwa 6+ | +5.5 = Isifungwe 6+.\n` +
    `💬 Uliza swali lolote kuhusu NBA hapa chini!`;
} else if (lower === 'cmd_results' || lower === '/results') {
  action = 'results';
} else if (isBankrollReq) {
  action = 'bankroll';
  instantReply = buildBetPawaSlip(detectedTzs || 10000);
} else if (lower === '/' || lower === '/start' || lower === '/help') {
  action = 'help';
  instantReply =
    `🦅 KARIBU NOELLYNE HERMES SPORTS AI v5.0!\n` +
    `━━━━━━━━━━━━━━━━━━━━━━\n` +
    `Bonyeza kitufe chochote hapa chini kupata taarifa papo hapo:\n` +
    `• ⚽ Football Leo — Kadi ya leo ya Sniper Football (Max 4 picks)\n` +
    `• 🏀 NBA Leo — Kadi ya NBA + 🏥 Injury Guard\n` +
    `• 📊 Matokeo — Rekodi yako halisi ya Google Sheet (Football vs NBA)\n` +
    `• 💰 Gawa Mtaji — BetPawa Slip Helper (au andika "Nina 20,000 leo")\n\n` +
    `💬 Unaweza pia kuniuliza swali lolote la kawaida kwa Kiswahili!`;
}

const prompt = `Wewe ni Noellyne Hermes Sports AI v5.0 — Mshauri Mkuu wa Football & NBA Betting kwa David Erick Mwijage.
PICKS ZA LEO (${lastTime}):
=== ⚽ FOOTBALL ===
${fbPicksText}

=== 🏀 NBA BASKETBALL (na Injury Guard) ===
${bbPicksText}

UJUMBE WA DAVID:
"${rawText}"

Jibu kwa Kiswahili safi, ufupi (mistari 4-8), bila Markdown (* au **) wala HTML tags.`;

return [{
  json: {
    skip: false,
    chatId,
    action,
    instantReply,
    detectedTzs: detectedTzs || 0,
    prompt,
    userText: rawText
  }
}];

// =============================================================
// Interactive Chat AI Router v5.1 (Resilient — NEVER goes silent!):
// - Instant <0.5s replies for One-Tap Buttons (⚽ Football, 🏀 NBA, 💰 BetPawa Slip, 📊 Results)
// - Gracefully survives expired Google Sheets OAuth instead of crashing silently!
// =============================================================
const sheetRows = $input.all();
const ctx = $('Parse & Build Context').first().json || {};
const chatId = ctx.chatId;

function cleanForTgHtml(t) {
  let s = String(t || '')
    .replace(/<think>[\s\S]*?<\/think>/gi, '')
    .replace(/<[^>]+>/g, '')
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/^\s*[\*\-]\s+/gm, '• ')
    .replace(/[`*_]/g, '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .trim();
  if (s.length > 3850) s = s.substring(0, 3847) + '...';
  return s;
}

const sheetErrItem = sheetRows.find(r => r.json && (r.json.error || r.json.message && !r.json.Match));
const sheetDown = Boolean(sheetErrItem);
const sheetErrMsg = sheetDown
  ? String((sheetErrItem.json.error && (sheetErrItem.json.error.message || sheetErrItem.json.error)) || sheetErrItem.json.message || 'Google Sheets disconnected').slice(0, 180)
  : '';

const BANKROLL_TZS = parseInt($env.HERMES_BANKROLL_TZS || '100000', 10);
const UNIT_TZS = Math.round(BANKROLL_TZS / 100);
const dedup = {};
let pendingFb = 0, pendingBb = 0;

if (!sheetDown) {
  for (const r of sheetRows) {
    const row = r.json || {};
    if (!row.Match) continue;
    const res = String(row.Result || '').trim().toUpperCase();
    const league = String(row.League || '');
    const market = String(row.Market || '');
    const isBasket = /nba|ncaa|basket|🏀/i.test(league) || /pts|spread|\sml\s/i.test(market);
    const conf = String(row.Confidence || '');
    const isRisky = conf.includes('RISKY') || conf.includes('🔴');

    if (res === 'PENDING' || res === '') {
      if (isBasket) pendingBb++; else pendingFb++;
      continue;
    }
    if (res !== 'WIN' && res !== 'LOSS') continue;

    const dt = String(row.Timestamp || '').slice(0, 10);
    const key = `${dt}::${String(row.Match).toLowerCase()}::${market.toLowerCase()}`;
    const odds = parseFloat(row.Odds) || 0;
    const units = parseFloat(row.StakeUnits) || 0;
    const payout = res === 'WIN' ? +(units * odds).toFixed(2) : 0;
    const profit = +(payout - units).toFixed(2);
    dedup[key] = { match: row.Match, market, odds, units, payout, profit, result: res, isBasket, isRisky, dt };
  }
}

const settledList = Object.values(dedup);
const safeAll = settledList.filter(x => !x.isRisky);
const safeFb = safeAll.filter(x => !x.isBasket);
const safeBb = safeAll.filter(x => x.isBasket);

function summarize(arr) {
  const w = arr.filter(x => x.result === 'WIN').length;
  const l = arr.length - w;
  const st = arr.reduce((a, b) => a + b.units, 0);
  const ret = arr.reduce((a, b) => a + b.payout, 0);
  const pr = ret - st;
  const roi = st > 0 ? (pr / st) * 100 : 0;
  const wr = arr.length > 0 ? (w / arr.length) * 100 : 0;
  return { n: arr.length, w, l, st, ret, pr, roi, wr, tzs: Math.round(pr * UNIT_TZS) };
}

const sAll = summarize(safeAll);
const sFb = summarize(safeFb);
const sBb = summarize(safeBb);

const liveResultsText = sheetDown
  ? (`⚠️ GOOGLE SHEETS OAUTH IME-EXPIRE!\n` +
     `━━━━━━━━━━━━━━━━━━━━━━\n` +
     `Sababu: ${sheetErrMsg}\n\n` +
     `🔧 Hatua ya sekunde 10:\n` +
     `1. Fungua: https://mwijay.duckdns.org/credentials\n` +
     `2. Bonyeza "Google Sheets account" → Reconnect.\n` +
     `3. Ili isijirudie kila siku 7: Google Cloud Console → OAuth Consent Screen → Publish App (Production).\n\n` +
     `💡 Picks za Football, NBA na BetPawa Slip bado zinafanya kazi hapa chini!`)
  : (`📊 MATOKEO LIVE KUTOKA GOOGLE SHEET (HermesPicks)\n` +
     `━━━━━━━━━━━━━━━━━━━━━━\n` +
     `💎 REKODI YA PESA HALISI (🟢 STRONG & 🟡 MODERATE):\n` +
     `• Jumla: ${sAll.w}W / ${sAll.l}L (${sAll.wr.toFixed(1)}% Win Rate)\n` +
     `• Faida Safi: ${sAll.pr >= 0 ? '+' : ''}${sAll.pr.toFixed(2)}u (${sAll.roi >= 0 ? '+' : ''}${sAll.roi.toFixed(1)}% ROI)\n` +
     `• Pochi (TZS): ${sAll.tzs >= 0 ? '+TZS ' : '-TZS '}${Math.abs(sAll.tzs).toLocaleString()} (Mtaji sasa: TZS ${(BANKROLL_TZS + sAll.tzs).toLocaleString()})\n\n` +
     `⚽ FOOTBALL (🟢/🟡): ${sFb.w}W / ${sFb.l}L (${sFb.wr.toFixed(1)}% WR) | ${sFb.pr >= 0 ? '+' : ''}${sFb.pr.toFixed(2)}u (${sFb.tzs >= 0 ? '+TZS ' : '-TZS '}${Math.abs(sFb.tzs).toLocaleString()})\n` +
     `🏀 BASKETBALL (🟢/🟡): ${sBb.w}W / ${sBb.l}L (${sBb.wr.toFixed(1)}% WR) | ${sBb.pr >= 0 ? '+' : ''}${sBb.pr.toFixed(2)}u (${sBb.tzs >= 0 ? '+TZS ' : '-TZS '}${Math.abs(sBb.tzs).toLocaleString()})\n\n` +
     `⏳ Mechi Zinasubiri (PENDING): ⚽ ${pendingFb} Football | 🏀 ${pendingBb} Basketball\n` +
     `🤖 Live Sync · mwijay.duckdns.org`);

// 1. Instant reply for [📊 Matokeo] / /results OR asking "matokeo vipi?"
const rawLow = String(ctx.rawText || '').toLowerCase();
if (ctx.action === 'results' || /\b(matokeo|results|rekodi|tumeishiaje|tumeshinda)\b/i.test(rawLow)) {
  return [{ json: { chatId, reply: cleanForTgHtml(liveResultsText) } }];
}

// 2. Instant reply for Football / NBA / BetPawa Slip / Help
if (ctx.instantReply) {
  return [{ json: { chatId, reply: cleanForTgHtml(ctx.instantReply) } }];
}

// 3. Free-text AI Chat
const prompt = `${ctx.prompt}\n\nTAKWINU HALISI ZA GOOGLE SHEET:\n${liveResultsText}`;
const ALLOWED = ['groq', 'gemini', 'openrouter'];
const MAX_TOK = 1000;
const SYS = 'Wewe ni Noellyne Hermes Sports AI v5.1 — mshauri wa Football na NBA betting kwa David Erick Mwijage. Jibu kwa Kiswahili safi, ufupi (chini ya maneno 240), bila Markdown (* au **) wala HTML tags.';
const ENV_MAP = { groq: 'GROQ_KEYS', gemini: 'GEMINI_KEYS', openrouter: 'OPENROUTER_KEYS' };
const URLS = { groq: 'https://api.groq.com/openai/v1/chat/completions', openrouter: 'https://openrouter.ai/api/v1/chat/completions' };
const MODELS = { groq: ['openai/gpt-oss-120b', 'llama-3.3-70b-versatile', 'openai/gpt-oss-20b'], gemini: ['gemini-2.5-flash'], openrouter: ['nvidia/nemotron-nano-9b-v2:free'] };
const sd = $getWorkflowStaticData('global'); sd.rr = sd.rr || {}; sd.cool = sd.cool || {};
const now = () => Date.now(); const DL = now() + 30000;
function getK(p) { return String($env[ENV_MAP[p]] || '').split(',').map(s => s.trim()).filter(Boolean); }
function cool(p, i, ms) { sd.cool[`${p}:${i}`] = now() + ms; }
function isC(p, i) { return (sd.cool[`${p}:${i}`] || 0) > now(); }
function nxt(p, l) { const c = Number.isFinite(sd.rr[p]) ? sd.rr[p] : -1; const n = (c + 1) % l; sd.rr[p] = n; return n; }

async function callOAI(prov, model, key) {
  const body = { model, messages: [{ role: 'system', content: SYS }, { role: 'user', content: prompt }], temperature: 0.3 };
  if (/gpt-oss/.test(model)) { body.max_completion_tokens = MAX_TOK; body.reasoning_effort = 'low'; }
  else { body.max_tokens = MAX_TOK; }
  const h = { 'Authorization': `Bearer ${key}`, 'Content-Type': 'application/json' };
  if (prov === 'openrouter') { h['HTTP-Referer'] = 'https://mwijay.duckdns.org'; }
  const r = await this.helpers.httpRequest({ method: 'POST', url: URLS[prov], headers: h, body, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000 });
  return { s: r.statusCode, t: r.body && r.body.choices && r.body.choices[0] && r.body.choices[0].message && r.body.choices[0].message.content };
}
async function callGem(model, key) {
  const r = await this.helpers.httpRequest({ method: 'POST', url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`, headers: { 'x-goog-api-key': key, 'Content-Type': 'application/json' }, body: { system_instruction: { parts: [{ text: SYS }] }, contents: [{ role: 'user', parts: [{ text: prompt }] }], generationConfig: { thinkingConfig: { thinkingBudget: 0 }, maxOutputTokens: MAX_TOK, temperature: 0.3 } }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000 });
  return { s: r.statusCode, t: r.body && r.body.candidates && r.body.candidates[0] && r.body.candidates[0].content && r.body.candidates[0].content.parts && r.body.candidates[0].content.parts.map(p => p.text).join('') };
}

for (const prov of ALLOWED) {
  if (now() > DL) break;
  const keys = getK(prov); if (!keys.length) continue;
  for (const model of MODELS[prov]) {
    if (now() > DL) break;
    for (let a = 0; a < Math.min(keys.length, 2); a++) {
      if (now() > DL) break;
      let idx = nxt(prov, keys.length), tr = 0;
      while (isC(prov, idx) && tr < keys.length) { idx = nxt(prov, keys.length); tr++; }
      if (isC(prov, idx)) break;
      try {
        const res = prov === 'gemini' ? await callGem.call(this, model, keys[idx]) : await callOAI.call(this, prov, model, keys[idx]);
        if (res.s >= 200 && res.s < 300 && res.t) {
          return [{ json: { chatId, reply: cleanForTgHtml(res.t) } }];
        }
        cool(prov, idx, res.s === 429 ? 60000 : 25000);
      } catch (e) { cool(prov, idx, 20000); }
    }
  }
}
return [{ json: { chatId, reply: '⚠️ Samahani David, AI iko busy sasa. Bonyeza vitufe hapa chini kwa majibu ya haraka.' } }];

// =============================================================
// Build Dual-Sport Fetch Plan + Live NBA Injury Report Feed
// =============================================================
const nowEat = $now.setZone('Africa/Dar_es_Salaam');
const d0 = nowEat.toFormat('yyyyLLdd');
const d1 = nowEat.plus({ days: 1 }).toFormat('yyyyLLdd');
const d2 = nowEat.plus({ days: 2 }).toFormat('yyyyLLdd');

const soccerLeagues = [
  { sport: 'soccer', slug: 'eng.1', name: 'EPL' },
  { sport: 'soccer', slug: 'esp.1', name: 'La Liga' },
  { sport: 'soccer', slug: 'ita.1', name: 'Serie A' },
  { sport: 'soccer', slug: 'ger.1', name: 'Bundesliga' },
  { sport: 'soccer', slug: 'fra.1', name: 'Ligue 1' },
  { sport: 'soccer', slug: 'uefa.champions', name: 'UCL' },
  { sport: 'soccer', slug: 'uefa.europa', name: 'UEL' },
  { sport: 'soccer', slug: 'uefa.nations', name: 'UEFA Nations' },
  { sport: 'soccer', slug: 'fifa.worldq.uefa', name: 'WCQ Europe' },
  { sport: 'soccer', slug: 'ned.1', name: 'Eredivisie' },
  { sport: 'soccer', slug: 'por.1', name: 'Liga Portugal' },
  { sport: 'soccer', slug: 'tur.1', name: 'Super Lig' },
  { sport: 'soccer', slug: 'bra.1', name: 'Brasileirão' },
  { sport: 'soccer', slug: 'usa.1', name: 'MLS' },
  { sport: 'soccer', slug: 'arg.1', name: 'Argentina Primera' },
  { sport: 'soccer', slug: 'eng.2', name: 'Championship' }
];

const basketLeagues = [
  { sport: 'basketball', slug: 'nba', name: 'NBA' },
  { sport: 'basketball', slug: 'mens-college-basketball', name: 'NCAAM' }
];

const list = [];
function pushLeague(l, dt) {
  list.push({
    ...l,
    dateStr: dt,
    url: `https://site.api.espn.com/apis/site/v2/sports/${l.sport}/${l.slug}/scoreboard?dates=${dt}`
  });
}

for (const l of soccerLeagues) {
  pushLeague(l, d0);
  pushLeague(l, d1);
}
for (const slug of ['eng.1', 'esp.1', 'ita.1', 'ger.1', 'fra.1']) {
  const found = soccerLeagues.find(x => x.slug === slug);
  if (found) pushLeague(found, d2);
}
for (const b of basketLeagues) {
  pushLeague(b, d0);
  pushLeague(b, d1);
}

// Live ESPN NBA Injury Report Feed for 🏥 NBA Injury Guard
list.push({
  sport: 'nba_injuries',
  slug: 'nba-injuries',
  name: 'NBA Injuries',
  dateStr: d0,
  url: 'https://site.api.espn.com/apis/site/v2/sports/basketball/nba/injuries'
});

return list.map(item => ({ json: item }));

// =============================================================
// HERMES QUANT MODEL v5.0 — SNIPER DUAL ENGINE + 🏥 NBA INJURY GUARD
// Max 4 Curated Football Picks + Max 4 Curated NBA Picks
// Checks live ESPN NBA Injury Report before assigning 🟢 STRONG!
// =============================================================
const items = $input.all();
const reqMeta = $('Build League List').all();
const nowMs = Date.now();

// Key NBA franchise stars / high-impact starters whose absence heavily shifts win odds
const NBA_STARS = [
  'Stephen Curry', 'Anthony Edwards', 'Joel Embiid', 'Giannis Antetokounmpo', 'Nikola Jokic',
  'LeBron James', 'Luka Doncic', 'Jayson Tatum', 'Shai Gilgeous-Alexander', 'Kevin Durant',
  'Devin Booker', 'Victor Wembanyama', 'Jalen Brunson', 'Tyrese Haliburton', 'Donovan Mitchell',
  'Ja Morant', 'Anthony Davis', 'Jimmy Butler', 'Kawhi Leonard', 'James Harden',
  'Damian Lillard', 'Paolo Banchero', 'Tyrese Maxey', 'De\'Aaron Fox', 'Cade Cunningham',
  'LaMelo Ball', 'Trae Young', 'Domantas Sabonis', 'Alperen Sengun', 'Darius Garland',
  'Evan Mobley', 'Chet Holmgren', 'Scottie Barnes', 'Zion Williamson', 'Brandon Ingram',
  'Bradley Beal', 'Kyrie Irving', 'Jaylen Brown', 'Karl-Anthony Towns', 'Rudy Gobert',
  'Pascal Siakam', 'Cooper Flagg', 'Kristaps Porzingis', 'Paul George', 'Bam Adebayo',
  'Tyler Herro', 'Franz Wagner', 'Jaren Jackson Jr.', 'Desmond Bane', 'Jalen Williams',
  'Jamal Murray', 'Donte DiVincenzo', 'Mikal Bridges', 'OG Anunoby', 'Julius Randle'
].map(s => s.toLowerCase());

// Pass 1: Build NBA Injury Map from live ESPN /nba/injuries payload
const nbaInjuryMap = {}; // lowercase team name -> { outNames, starOuts, dtdNames }
for (let idx = 0; idx < items.length; idx++) {
  const meta = (reqMeta[idx] && reqMeta[idx].json) || {};
  const body = items[idx].json || {};
  if (meta.sport === 'nba_injuries' || Array.isArray(body.injuries)) {
    for (const teamBlock of (body.injuries || [])) {
      const tName = String(teamBlock.displayName || '').toLowerCase().trim();
      if (!tName) continue;
      const outNames = [];
      const starOuts = [];
      const dtdNames = [];
      for (const inj of (teamBlock.injuries || [])) {
        const status = String(inj.status || '').toLowerCase();
        const player = String((inj.athlete && inj.athlete.displayName) || '').trim();
        if (!player) continue;
        if (status === 'out' || status === 'doubtful') {
          outNames.push(player);
          if (NBA_STARS.includes(player.toLowerCase())) {
            starOuts.push(player);
          }
        } else if (status.includes('day-to-day') || status.includes('questionable')) {
          dtdNames.push(player);
        }
      }
      nbaInjuryMap[tName] = { outNames, starOuts, dtdNames };
    }
  }
}

function getTeamInjuries(teamDisplayName) {
  const key = String(teamDisplayName || '').toLowerCase().trim();
  if (nbaInjuryMap[key]) return nbaInjuryMap[key];
  for (const k of Object.keys(nbaInjuryMap)) {
    if (k.includes(key) || key.includes(k)) return nbaInjuryMap[k];
  }
  return { outNames: [], starOuts: [], dtdNames: [] };
}

function amToDec(r) {
  if (r == null || r === '') return null;
  const n = parseFloat(String(r).replace('+', ''));
  if (isNaN(n) || n === 0) return null;
  return n > 0 ? +(1 + n / 100).toFixed(2) : +(1 + 100 / Math.abs(n)).toFixed(2);
}

function formScore(f) {
  if (!f) return 0.5;
  let p = 0, len = 0;
  for (const c of String(f)) {
    if (c === 'W') { p += 3; len++; }
    else if (c === 'D') { p += 1; len++; }
    else if (c === 'L') { len++; }
  }
  return len > 0 ? p / (len * 3) : 0.5;
}

function recScore(recStr, isSoccer) {
  if (!recStr) return 0.5;
  const parts = String(recStr).split('-').map(x => parseInt(x, 10) || 0);
  if (isSoccer && parts.length === 3) {
    const [w, d, l] = parts;
    const g = w + d + l;
    return g > 0 ? (w * 3 + d) / (g * 3) : 0.5;
  }
  if (parts.length >= 2) {
    const w = parts[0], l = parts[1];
    const g = w + l;
    return g > 0 ? w / g : 0.5;
  }
  return 0.5;
}

function fmtEat(evt) {
  try {
    const comp = (evt.competitions && evt.competitions[0]) || {};
    const iso = evt.date || comp.date || evt.startDate || '';
    if (!iso) return 'TBD EAT';
    const d = new Date(iso);
    if (isNaN(d.getTime())) return 'TBD EAT';
    const dayPart = d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', timeZone: 'Africa/Dar_es_Salaam' });
    const timePart = d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Africa/Dar_es_Salaam' });
    return `${dayPart} ${timePart} EAT`;
  } catch (e) {
    return 'TBD EAT';
  }
}

function getIso(evt) {
  try {
    const comp = (evt.competitions && evt.competitions[0]) || {};
    const iso = evt.date || comp.date || evt.startDate || '';
    if (!iso) return '';
    const d = new Date(iso);
    return isNaN(d.getTime()) ? '' : d.toISOString();
  } catch (e) {
    return '';
  }
}

const seenEventIds = new Set();
const fbCandidates = [];
const nbaCandidates = [];
const ncaaMlCandidates = [];
const injuryAlerts = [];
let totalSoccerEvents = 0;
let totalBasketEvents = 0;

for (let idx = 0; idx < items.length; idx++) {
  const item = items[idx];
  const meta = (reqMeta[idx] && reqMeta[idx].json) || {};
  if (meta.sport === 'nba_injuries') continue;

  const events = (item.json && item.json.events) || [];
  const lgObj = (item.json && item.json.leagues && item.json.leagues[0]) || {};
  const uid = String(lgObj.uid || '');
  const sport = meta.sport || (uid.startsWith('s:40') ? 'basketball' : 'soccer');
  const leagueName = meta.name || lgObj.abbreviation || lgObj.name || 'League';

  for (const ev of events) {
    if (!ev || !ev.id) continue;
    const evId = String(ev.id);
    if (seenEventIds.has(evId)) continue;

    const completed = !!(ev.status && ev.status.type && ev.status.type.completed);
    if (completed) continue;

    const kIso = getIso(ev);
    if (kIso && new Date(kIso).getTime() < nowMs - 15 * 60 * 1000) continue;

    seenEventIds.add(evId);

    const comp = (ev.competitions && ev.competitions[0]) || {};
    const cs = comp.competitors || [];
    const h = cs.find(c => c.homeAway === 'home') || {};
    const a = cs.find(c => c.homeAway === 'away') || {};
    const home = (h.team && h.team.displayName) || 'Home';
    const away = (a.team && a.team.displayName) || 'Away';
    if (home === 'TBD' || away === 'TBD') continue;

    const o = (comp.odds && comp.odds[0]) || {};

    if (sport === 'soccer') {
      totalSoccerEvents++;
      const hForm = h.form || '-----', aForm = a.form || '-----';
      const hRec = (h.records && h.records[0] && h.records[0].summary) || '0-0-0';
      const aRec = (a.records && a.records[0] && a.records[0].summary) || '0-0-0';

      const hDec = amToDec(o.moneyline && o.moneyline.home && o.moneyline.home.close && o.moneyline.home.close.odds);
      const aDec = amToDec(o.moneyline && o.moneyline.away && o.moneyline.away.close && o.moneyline.away.close.odds);
      const dDec = amToDec((o.moneyline && o.moneyline.draw && o.moneyline.draw.close && o.moneyline.draw.close.odds) || (o.drawOdds && o.drawOdds.moneyLine));
      const ouLine = o.overUnder || 2.5;
      const overDec = amToDec(o.total && o.total.over && o.total.over.close && o.total.over.close.odds);
      const underDec = amToDec(o.total && o.total.under && o.total.under.close && o.total.under.close.odds);
      if (!hDec || !aDec) continue;

      const hs = 0.55 * formScore(h.form) + 0.45 * recScore(hRec, true);
      const as = 0.55 * formScore(a.form) + 0.45 * recScore(aRec, true);
      const sDiff = hs - as;

      const impH = 1 / hDec, impA = 1 / aDec, impD = dDec ? 1 / dDec : 0.27;
      const impSum = impH + impA + impD;
      const fairH = impH / impSum, fairD = impD / impSum, fairA = impA / impSum;

      const alpha = sDiff * 0.22 + (hs >= 0.55 ? 0.03 : 0);
      const modH = Math.max(0.12, Math.min(0.86, fairH + alpha));
      const modA = Math.max(0.10, Math.min(0.84, fairA - sDiff * 0.22 + (as >= 0.58 ? 0.03 : 0)));
      const modD = Math.max(0.14, Math.min(0.33, fairD + (0.22 - Math.abs(sDiff)) * 0.08));

      const opts = [];
      if (hDec >= 1.25 && hDec <= 2.40 && modH >= 0.56) {
        opts.push({ market: `${home} Win (1)`, explain: `${home} kushinda nyumbani`, odds: hDec, prob: modH });
      }
      if (aDec >= 1.30 && aDec <= 2.40 && modA >= 0.56) {
        opts.push({ market: `${away} Win (2)`, explain: `${away} kushinda ugenini`, odds: aDec, prob: modA });
      }
      const dc1XProb = Math.min(0.88, modH + modD);
      const dc1XOdds = +((1 / (fairH + fairD)) * 0.98).toFixed(2);
      if (dc1XOdds >= 1.25 && dc1XOdds <= 1.88 && dc1XProb >= 0.65 && sDiff >= -0.05) {
        opts.push({ market: 'DC 1X', explain: `${home} kushinda AU Sare`, odds: dc1XOdds, prob: dc1XProb });
      }
      const dcX2Prob = Math.min(0.88, modA + modD);
      const dcX2Odds = +((1 / (fairA + fairD)) * 0.98).toFixed(2);
      if (dcX2Odds >= 1.25 && dcX2Odds <= 1.88 && dcX2Prob >= 0.65 && sDiff <= 0.05) {
        opts.push({ market: 'DC X2', explain: `${away} kushinda AU Sare`, odds: dcX2Odds, prob: dcX2Prob });
      }
      if (overDec && underDec) {
        const impO = 1 / overDec, impU = 1 / underDec;
        const fairO = impO / (impO + impU), fairU = impU / (impO + impU);
        const goalPulse = (hs + as - 0.92) * 0.22 + Math.abs(sDiff) * 0.10;
        const modOver = Math.max(0.25, Math.min(0.80, fairO + goalPulse));
        const modUnder = Math.max(0.25, Math.min(0.80, fairU - goalPulse));
        if (overDec >= 1.42 && overDec <= 2.20 && modOver >= 0.58) {
          opts.push({ market: `OVER ${ouLine}`, explain: `Jumla ya magoli kuzidi ${ouLine}`, odds: overDec, prob: modOver });
        }
        if (underDec >= 1.42 && underDec <= 2.20 && modUnder >= 0.58) {
          opts.push({ market: `UNDER ${ouLine}`, explain: `Jumla ya magoli chini ya ${ouLine}`, odds: underDec, prob: modUnder });
        }
      }

      let best = null;
      for (const op of opts) {
        const evVal = op.prob * op.odds - 1;
        if (evVal < 0.015) continue;
        const sharpScore = (evVal * 100) + (op.prob * 100 - 55) * 0.85;
        if (!best || sharpScore > best.sharpScore) {
          const probPct = +(op.prob * 100).toFixed(1);
          const edgePct = +(evVal * 100).toFixed(1);
          const tier = (probPct >= 63 && edgePct >= 2.5) || (probPct >= 68 && edgePct >= 1.5)
            ? '🟢 STRONG'
            : (probPct >= 56 && edgePct >= 1.5 ? '🟡 MODERATE' : '🔴 RISKY');
          const kellyF = evVal > 0 ? evVal / (op.odds - 1) : 0.01;
          const rawUnits = +(0.25 * kellyF * 100).toFixed(2);
          const units = tier.includes('STRONG')
            ? Math.min(3.00, Math.max(2.00, rawUnits))
            : (tier.includes('MODERATE') ? Math.min(1.50, Math.max(1.00, rawUnits)) : 0.50);

          best = {
            id: evId,
            sport: 'soccer',
            league: `⚽ ${leagueName}`,
            match: `${home} vs ${away}`,
            kickoff: fmtEat(ev),
            kickoffISO: kIso,
            market: op.market,
            explain: op.explain,
            odds: op.odds,
            probPct,
            edgePct,
            tier,
            group: probPct >= 70 ? 'ANCHOR' : 'VALUE',
            units,
            hForm,
            aForm,
            hRec,
            aRec,
            sharpScore
          };
        }
      }
      if (best && !best.tier.includes('RISKY')) fbCandidates.push(best);
    } else {
      // BASKETBALL — NBA Priority + 🏥 LIVE NBA INJURY GUARD
      totalBasketEvents++;
      const isNBA = leagueName === 'NBA' || meta.slug === 'nba';
      const hInj = isNBA ? getTeamInjuries(home) : { outNames: [], starOuts: [], dtdNames: [] };
      const aInj = isNBA ? getTeamInjuries(away) : { outNames: [], starOuts: [], dtdNames: [] };

      if (isNBA && (hInj.starOuts.length > 0 || aInj.starOuts.length > 0)) {
        const parts = [];
        if (hInj.starOuts.length) parts.push(`${home}: ${hInj.starOuts.join(', ')} OUT`);
        if (aInj.starOuts.length) parts.push(`${away}: ${aInj.starOuts.join(', ')} OUT`);
        injuryAlerts.push(parts.join(' | '));
      }

      const hRec = (h.records && h.records[0] && h.records[0].summary) || '0-0';
      const aRec = (a.records && a.records[0] && a.records[0].summary) || '0-0';
      const hHomeRec = (h.records && h.records.find(r => r.type === 'home') && h.records.find(r => r.type === 'home').summary) || hRec;
      const aRoadRec = (a.records && a.records.find(r => r.type === 'road') && a.records.find(r => r.type === 'road').summary) || aRec;
      const getStat = (cObj, n) => {
        const s = (cObj.statistics || []).find(x => x.name === n);
        return s ? parseFloat(s.displayValue) : null;
      };
      const defaultPPG = isNBA ? 113.5 : 75.0;
      const hPPG = getStat(h, 'avgPoints') || defaultPPG;
      const aPPG = getStat(a, 'avgPoints') || defaultPPG;
      const hFG = getStat(h, 'fieldGoalPct') || 46.0;
      const aFG = getStat(a, 'fieldGoalPct') || 46.0;

      const hML = amToDec(o.moneyline && o.moneyline.home && o.moneyline.home.close && o.moneyline.home.close.odds);
      const aML = amToDec(o.moneyline && o.moneyline.away && o.moneyline.away.close && o.moneyline.away.close.odds);
      const spRaw = o.pointSpread && o.pointSpread.home && o.pointSpread.home.close && o.pointSpread.home.close.line;
      const spLine = parseFloat(spRaw !== undefined ? spRaw : (o.spread || 0));
      const hSpDec = amToDec(o.pointSpread && o.pointSpread.home && o.pointSpread.home.close && o.pointSpread.home.close.odds) || 1.91;
      const aSpDec = amToDec(o.pointSpread && o.pointSpread.away && o.pointSpread.away.close && o.pointSpread.away.close.odds) || 1.91;
      const ouLine = parseFloat(o.overUnder || 0);
      const overDec = amToDec(o.total && o.total.over && o.total.over.close && o.total.over.close.odds) || 1.91;
      const underDec = amToDec(o.total && o.total.under && o.total.under.close && o.total.under.close.odds) || 1.91;

      if (!hML && !spLine) continue;

      const hWinPct = 0.6 * recScore(hRec, false) + 0.4 * recScore(hHomeRec, false);
      const aWinPct = 0.6 * recScore(aRec, false) + 0.4 * recScore(aRoadRec, false);
      const winDiff = hWinPct - aWinPct;

      // Injury delta: superstar OUT = -7.5% penalty on own team, +3% boost when opponent loses star!
      const hInjPen = (hInj.starOuts.length > 0 ? 0.075 : 0) + (hInj.outNames.length >= 4 ? 0.025 : 0);
      const aInjPen = (aInj.starOuts.length > 0 ? 0.075 : 0) + (aInj.outNames.length >= 4 ? 0.025 : 0);
      const netPtsDiff = (hPPG - aPPG) * 0.65 + (hFG - aFG) * 0.55 + 2.5 - (hInjPen - aInjPen) * 45;

      function buildInjuryNote(side) {
        if (!isNBA) return '';
        const own = side === 'home' ? hInj : (side === 'away' ? aInj : null);
        const opp = side === 'home' ? aInj : (side === 'away' ? hInj : null);
        if (!own) return '';
        const notes = [];
        if (own.starOuts.length > 0) notes.push(`⚠️ ${own.starOuts.join(', ')} OUT (Downgraded)`);
        else if (own.outNames.length >= 4) notes.push(`⚠️ ${own.outNames.length} wachezaji OUT`);
        if (opp.starOuts.length > 0) notes.push(`Mpinzani: ${opp.starOuts.join(', ')} OUT ✅`);
        if (!notes.length) return 'Clean ✅ (Hakuna star OUT)';
        return notes.join(' | ');
      }

      const opts = [];
      // 1. Moneyline
      if (hML && aML) {
        const impH = 1 / hML, impA = 1 / aML;
        const fairH = impH / (impH + impA), fairA = impA / (impH + impA);
        const modH = Math.max(0.15, Math.min(0.88, fairH + winDiff * 0.18 - hInjPen + (aInj.starOuts.length > 0 ? 0.03 : 0)));
        const modA = Math.max(0.15, Math.min(0.88, fairA - winDiff * 0.18 - aInjPen + (hInj.starOuts.length > 0 ? 0.03 : 0)));
        if (hML >= 1.24 && hML <= 2.30 && modH >= 0.57) {
          opts.push({
            market: `${home} ML (Win)`,
            explain: `${home} kushinda mechi (pamoja na Overtime)`,
            odds: hML, prob: modH, bonus: 6,
            blockStrong: hInj.starOuts.length > 0,
            injuryNote: buildInjuryNote('home')
          });
        }
        if (aML >= 1.24 && aML <= 2.30 && modA >= 0.57) {
          opts.push({
            market: `${away} ML (Win)`,
            explain: `${away} kushinda mechi (pamoja na Overtime)`,
            odds: aML, prob: modA, bonus: 6,
            blockStrong: aInj.starOuts.length > 0,
            injuryNote: buildInjuryNote('away')
          });
        }
      }
      // 2. NBA Point Spread
      if (isNBA && !isNaN(spLine) && spLine !== 0 && Math.abs(spLine) <= 11.5) {
        const marginEdge = Math.max(-8, Math.min(8, netPtsDiff + spLine));
        const impHS = 1 / hSpDec, impAS = 1 / aSpDec;
        const fairHS = impHS / (impHS + impAS), fairAS = impAS / (impHS + impAS);
        const modHS = Math.max(0.35, Math.min(0.66, fairHS + (marginEdge / 12) * 0.12 - (hInj.starOuts.length > 0 ? 0.04 : 0)));
        const modAS = Math.max(0.35, Math.min(0.66, fairAS - (marginEdge / 12) * 0.12 - (aInj.starOuts.length > 0 ? 0.04 : 0)));
        const hLineStr = spLine > 0 ? `+${spLine}` : `${spLine}`;
        const aLineVal = -spLine;
        const aLineStr = aLineVal > 0 ? `+${aLineVal}` : `${aLineVal}`;
        if (modHS >= 0.57) {
          opts.push({
            market: `SPREAD ${home} ${hLineStr}`,
            explain: spLine < 0
              ? `${home} kushinda kwa tofauti ya pointi ${Math.ceil(Math.abs(spLine))}+`
              : `${home} kushinda AU kutofungwa zaidi ya pointi ${Math.floor(spLine)}`,
            odds: hSpDec, prob: modHS, bonus: 2,
            blockStrong: hInj.starOuts.length > 0,
            injuryNote: buildInjuryNote('home')
          });
        }
        if (modAS >= 0.57) {
          opts.push({
            market: `SPREAD ${away} ${aLineStr}`,
            explain: aLineVal < 0
              ? `${away} kushinda kwa tofauti ya pointi ${Math.ceil(Math.abs(aLineVal))}+`
              : `${away} kushinda AU kutofungwa zaidi ya pointi ${Math.floor(aLineVal)}`,
            odds: aSpDec, prob: modAS, bonus: 2,
            blockStrong: aInj.starOuts.length > 0,
            injuryNote: buildInjuryNote('away')
          });
        }
      }
      // 3. NBA Totals ONLY (Strict & injury-aware)
      if (isNBA && ouLine >= 205 && ouLine <= 245) {
        const starOutPenaltyPts = (hInj.starOuts.length + aInj.starOuts.length) * 4.0;
        const regressedTotal = 0.55 * (hPPG + aPPG - starOutPenaltyPts) + 0.45 * ouLine + ((hFG + aFG - 93.0) * 0.4);
        const totalDiff = Math.max(-9, Math.min(9, regressedTotal - ouLine));
        const impO = 1 / overDec, impU = 1 / underDec;
        const fairO = impO / (impO + impU), fairU = impU / (impO + impU);
        const modO = Math.max(0.38, Math.min(0.65, fairO + (totalDiff / 12) * 0.12));
        const modU = Math.max(0.38, Math.min(0.65, fairU - (totalDiff / 12) * 0.12));
        const totInjNote = (hInj.starOuts.length + aInj.starOuts.length > 0)
          ? `Stars OUT: ${[...hInj.starOuts, ...aInj.starOuts].join(', ')}`
          : 'Clean ✅';
        if (modO >= 0.60 && (hInj.starOuts.length + aInj.starOuts.length === 0)) {
          opts.push({ market: `OVER ${ouLine} Pts`, explain: `Jumla ya pointi kuzidi ${ouLine}`, odds: overDec, prob: modO, bonus: 0, blockStrong: false, injuryNote: totInjNote });
        }
        if (modU >= 0.60) {
          opts.push({ market: `UNDER ${ouLine} Pts`, explain: `Jumla ya pointi chini ya ${ouLine}`, odds: underDec, prob: modU, bonus: 0, blockStrong: false, injuryNote: totInjNote });
        }
      }

      let best = null;
      for (const op of opts) {
        const evVal = op.prob * op.odds - 1;
        if (evVal < 0.015) continue;
        const sharpScore = (evVal * 100) + (op.prob * 100 - 55) * 0.8 + (op.bonus || 0) - (op.blockStrong ? 8 : 0);
        if (!best || sharpScore > best.sharpScore) {
          const probPct = +(op.prob * 100).toFixed(1);
          const edgePct = +(evVal * 100).toFixed(1);
          let tier = (probPct >= 60 && edgePct >= 2.5) || (probPct >= 70 && edgePct >= 1.5)
            ? '🟢 STRONG'
            : (probPct >= 56 && edgePct >= 1.5 ? '🟡 MODERATE' : '🔴 RISKY');
          // 🏥 NBA Injury Guard Rule: NEVER allow 🟢 STRONG when backed team's superstar is OUT!
          if (op.blockStrong && tier.includes('STRONG')) {
            tier = '🟡 MODERATE';
          }
          const kellyF = evVal > 0 ? evVal / (op.odds - 1) : 0.01;
          const rawUnits = +(0.25 * kellyF * 100).toFixed(2);
          const units = tier.includes('STRONG')
            ? Math.min(3.00, Math.max(2.00, rawUnits))
            : (tier.includes('MODERATE') ? Math.min(1.50, Math.max(1.00, rawUnits)) : 0.50);

          best = {
            id: evId,
            sport: 'basketball',
            league: `🏀 ${leagueName}`,
            match: `${home} vs ${away}`,
            kickoff: fmtEat(ev),
            kickoffISO: kIso,
            market: op.market,
            explain: op.explain,
            injuryNote: op.injuryNote || '',
            odds: op.odds,
            probPct,
            edgePct,
            tier,
            group: (probPct >= 70 && !op.blockStrong) ? 'ANCHOR' : 'VALUE',
            units,
            hForm: `${hRec} (${hPPG.toFixed(1)} PPG)`,
            aForm: `${aRec} (${aPPG.toFixed(1)} PPG)`,
            hRec,
            aRec,
            sharpScore
          };
        }
      }
      if (best && !best.tier.includes('RISKY')) {
        if (isNBA) nbaCandidates.push(best);
        else ncaaMlCandidates.push(best);
      }
    }
  }
}

function curateTop4(list) {
  const sorted = [...list].sort((x, y) => y.sharpScore - x.sharpScore);
  const anchors = sorted.filter(p => p.group === 'ANCHOR').slice(0, 2);
  const values = sorted.filter(p => p.group !== 'ANCHOR').slice(0, 2);
  const combined = [...anchors, ...values];
  for (const p of sorted) {
    if (combined.length >= 4) break;
    if (!combined.find(x => x.id === p.id)) combined.push(p);
  }
  return combined.slice(0, 4);
