  return filtered.length ? filtered : clean;
};

function teamScore(a, b) {
  const ta = normTokens(a), tb = normTokens(b);
  if (!ta.length || !tb.length) return 0;
  let hits = 0;
  for (const x of ta) {
    if (tb.some(y => y === x || y.includes(x) || x.includes(y))) hits++;
